function create(seed) {
  if (!Number.isFinite(seed)) throw new Error("rng seed must be a number, got " + seed);
  const next = mulberry32(Math.trunc(seed));
  return {
    next,
    int(n) {
      return Math.floor(next() * n);
    },
    pick(list) {
      return list[Math.floor(next() * list.length)];
    },
  };
}

